/* Triều Ngân | Wax & Wane (Othello). One-file bot for the kit's worker and arena. */
const FILE_A = 0x01010101, FILE_H = 0x80808080;
const INSIDE_FILES = 0x7e7e7e7e;
const HALF_CORNER = 0x00000081, FAR_CORNER = 0x81000000;
const WINS = 8192, INF = 11000;
const TIME_UP = {};
const LOWER = 1, UPPER = 2, EXACT = 3;

function pop(bits) {
  bits -= (bits >>> 1) & 0x55555555;
  bits = (bits & 0x33333333) + ((bits >>> 2) & 0x33333333);
  return Math.imul((bits + (bits >>> 4)) & 0x0f0f0f0f, 0x01010101) >>> 24;
}

const bitIndex = bit => 31 - Math.clz32(bit);
const finalScore = diff => diff ? Math.sign(diff) * WINS + diff * 32 : 0;

// Pack the opposing runs in parallel. Mask the sides of the board before propagating across files.
function generate(p, ph, o, oh, out) {
  const x = o & INSIDE_FILES, xh = oh & INSIDE_FILES;
  let a = x & (p << 1), b = xh & (ph << 1);
  a |= x & (a << 1); b |= xh & (b << 1);
  let u = x & (x << 1), v = xh & (xh << 1);
  a |= u & (a << 2); b |= v & (b << 2);
  a |= u & (a << 2); b |= v & (b << 2);
  let lo = a << 1, hi = b << 1;

  a = x & (p >>> 1); b = xh & (ph >>> 1);
  a |= x & (a >>> 1); b |= xh & (b >>> 1);
  u = x & (x >>> 1); v = xh & (xh >>> 1);
  a |= u & (a >>> 2); b |= v & (b >>> 2);
  a |= u & (a >>> 2); b |= v & (b >>> 2);
  lo |= a >>> 1; hi |= b >>> 1;

  for (let s = 7; s <= 9; s++) {
    const back = 32 - s, twice = s * 2, back2 = 32 - twice;
    const m = s === 8 ? o : x, mh = s === 8 ? oh : xh;
    a = m & (p << s); b = mh & ((ph << s) | (p >>> back));
    b |= mh & ((b << s) | (a >>> back)); a |= m & (a << s);
    u = m & (m << s); v = mh & ((mh << s) | (m >>> back));
    b |= v & ((b << twice) | (a >>> back2)); a |= u & (a << twice);
    b |= v & ((b << twice) | (a >>> back2)); a |= u & (a << twice);
    lo |= a << s; hi |= (b << s) | (a >>> back);

    a = m & ((p >>> s) | (ph << back)); b = mh & (ph >>> s);
    a |= m & ((a >>> s) | (b << back)); b |= mh & (b >>> s);
    u = m & ((m >>> s) | (mh << back)); v = mh & (mh >>> s);
    a |= u & ((a >>> twice) | (b << back2)); b |= v & (b >>> twice);
    a |= u & ((a >>> twice) | (b << back2)); b |= v & (b >>> twice);
    lo |= (a >>> s) | (b << back); hi |= b >>> s;
  }
  out.lo = lo & ~(p | o);
  out.hi = hi & ~(ph | oh);
}

const lineFlips = new Uint8Array(8 * 65536);
for (let where = 0; where < 8; where++) {
  const base = where << 16;
  function fill(i, mine, theirs) {
    if (i < 8) {
      fill(i + 1, mine, theirs);
      if (i !== where) {
        fill(i + 1, mine | (1 << i), theirs);
        fill(i + 1, mine, theirs | (1 << i));
      }
      return;
    }
    let result = 0;
    for (const step of [-1, 1]) {
      let at = where + step, run = 0;
      while (at >= 0 && at < 8 && (theirs & (1 << at))) { run |= 1 << at; at += step; }
      if (at >= 0 && at < 8 && (mine & (1 << at))) result |= run;
    }
    lineFlips[base | (mine << 8) | theirs] = result;
  }
  fill(0, 0, 0);
}

// Nonhorizontal lines are gathered into a byte by rank and then scattered back into the board.
const lanes = Array.from({ length: 64 }, () => []);
for (const slope of [0, 1, -1]) {
  const multiplier = slope === 0 ? 0x01020408 : slope === 1 ? 0x01010101 : 0x01041040;
  for (let intercept = -7; intercept <= 14; intercept++) {
    const squares = new Int8Array(8).fill(-1);
    let lo = 0, hi = 0, count = 0;
    for (let y = 0; y < 8; y++) {
      const x = intercept + slope * y;
      if (x < 0 || x >= 8) continue;
      const sq = y * 8 + x;
      squares[y] = sq; count++;
      if (sq < 32) lo |= 1 << sq;
      else hi |= 1 << (sq - 32);
    }
    if (count < 3) continue;
    const scatterLo = new Int32Array(256), scatterHi = new Int32Array(256);
    for (let bits = 1; bits < 256; bits++) {
      const sq = squares[bitIndex(bits & -bits)], rest = bits & (bits - 1);
      scatterLo[bits] = scatterLo[rest]; scatterHi[bits] = scatterHi[rest];
      if (sq >= 32) scatterHi[bits] |= 1 << (sq - 32);
      else if (sq >= 0) scatterLo[bits] |= 1 << sq;
    }
    const data = { lo, hi, shift: intercept, shiftHi: intercept + slope * 4, multiplier, scatterLo, scatterHi };
    for (const sq of squares) if (sq >= 0) lanes[sq].push(data);
  }
}

function gather(bits, mask, shift, multiplier) {
  const x = bits & mask;
  return (Math.imul(shift < 0 ? x << -shift : x >>> shift, multiplier) >>> 24) & 15;
}

function flips(p, ph, o, oh, sq, out) {
  const shift = sq & 24, row = (sq & 7) << 16, top = sq < 32;
  const horizontal = lineFlips[row | ((((top ? p : ph) >>> shift) & 255) << 8) | (((top ? o : oh) >>> shift) & 255)] << shift;
  let lo = top ? horizontal : 0, hi = top ? 0 : horizontal;
  const base = (sq >>> 3) << 16, lines = lanes[sq];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i], mult = line.multiplier;
    const a = gather(p, line.lo, line.shift, mult) | (gather(ph, line.hi, line.shiftHi, mult) << 4);
    const b = gather(o, line.lo, line.shift, mult) | (gather(oh, line.hi, line.shiftHi, mult) << 4);
    const bits = lineFlips[base | (a << 8) | b];
    lo |= line.scatterLo[bits]; hi |= line.scatterHi[bits];
  }
  out.lo = lo; out.hi = hi;
}

function encode(S, out) {
  let p = 0, ph = 0, o = 0, oh = 0;
  for (let c = 0; c < 64; c++) {
    const value = S.b[c];
    if (!value) continue;
    const mine = value === S.turn + 1;
    if (c < 32) {
      if (mine) p |= 1 << c;
      else o |= 1 << c;
    } else if (mine) ph |= 1 << (c - 32);
    else oh |= 1 << (c - 32);
  }
  out.p = p; out.ph = ph; out.o = o; out.oh = oh;
}

const edgeRuns = new Uint8Array(256);
for (let k = 1; k < 256; k++) {
  let stable = 0;
  for (let b = 1; b < 256 && (k & b); b <<= 1) stable |= b;
  for (let b = 128; b > 0 && (k & b); b >>>= 1) stable |= b;
  edgeRuns[k] = stable;
}
const file = (l, h, x) => gather(l, FILE_A << x, x, 0x01020408) | (gather(h, FILE_A << x, x, 0x01020408) << 4);
const secure = (a, b) => (a | b) === 255 ? a : edgeRuns[a];

function stableEdges(p, ph, o, oh) {
  const top = secure(p & 255, o & 255), bottom = secure(ph >>> 24, oh >>> 24);
  const left = secure(file(p, ph, 0), file(o, oh, 0)), right = secure(file(p, ph, 7), file(o, oh, 7));
  return pop(top) + pop(bottom) + pop(left & 126) + pop(right & 126);
}

const POSITION = new Int16Array([
  96, -25, 16, 12, 12, 16, -25, 96,
  -25, -46, -6, -4, -4, -6, -46, -25,
  16, -6, 9, 4, 4, 9, -6, 16,
  12, -4, 4, 1, 1, 4, -4, 12,
  12, -4, 4, 1, 1, 4, -4, 12,
  16, -6, 9, 4, 4, 9, -6, 16,
  -25, -46, -6, -4, -4, -6, -46, -25,
  96, -25, 16, 12, 12, 16, -25, 96,
]);
const QUADRANT = Uint8Array.from({ length: 64 }, (_, sq) => 1 << ((sq >= 32 ? 2 : 0) + ((sq & 4) ? 1 : 0)));

const valueMob = new Int16Array(65), valueFront = new Int16Array(65), valueDisc = new Int16Array(65);
const valueEdge = new Int16Array(65), valueCorner = new Int16Array(65);
for (let e = 0; e <= 64; e++) {
  valueMob[e] = 40 + Math.min(24, e);
  valueFront[e] = 10 + Math.min(22, (e * 3) >> 2);
  valueDisc[e] = e > 35 ? -5 : e > 17 ? 13 - (e >> 2) : 27 - e;
  valueEdge[e] = 44 + (e >> 2);
  valueCorner[e] = 225 + e;
}

function cornerDanger(mine, theirs) {
  const all = mine | theirs;
  let points = 0;
  if (!(all & 1)) {
    points += ((theirs >>> 9) & 1) * 188 - ((mine >>> 9) & 1) * 188;
    points += (pop(theirs & 0x102) - pop(mine & 0x102)) * 66;
  }
  if (!(all & 128)) {
    points += ((theirs >>> 14) & 1) * 188 - ((mine >>> 14) & 1) * 188;
    points += (pop(theirs & 0x8040) - pop(mine & 0x8040)) * 66;
  }
  return points;
}

